INSERT INTO `cms_sections` VALUES (22,'home_places_to_explore','Places To Explore — Diverse, Spell-Binding India','India’s languages, religions, dance, music, architecture, food, and customs differ wonderfully across every state. A spell-binding country where people of unlike communities live together in oneness.','India contains majestic peaks dusted with glistening snow, sun-drenched beaches, ancient hand-carved temples, and sprawling cities rich with history. The southern part of the country, surrounded by the Arabian Sea and the Bay of Bengal, is listed among the most picturesque destinations on Earth.',317,1,'inactive',NULL,NULL,'2026-09-28 05:33:10','2026-11-06 07:25:56'),(23,'home_things_to_do','Things To Do — Handcrafted Travel Experiences','Whether planning a family vacation, religious and cultural pilgrimage, wildlife safari, or romantic getaway, India offers an astonishing variety of activities.','Browse through our curated attraction categories — from Escorted City Tours and Classical Art & Dance Shows, to National Park Wildlife Safaris, Spice Plantation Walks, and Beachside Dining across South India.',450,2,'inactive',NULL,NULL,'2026-09-28 05:33:10','2026-11-06 07:26:22'),(24,'home_why_travel_with_us','Why Travel With Wonderer South India','We believe that planning the details of your trip should be as enjoyable and effortless as the journey itself.','With 24/7 dedicated support, certified local tour guides, tailored private itineraries, and guaranteed transparent pricing, we deliver world-class travel across South India.',261,3,'inactive',NULL,NULL,'2026-09-28 05:33:10','2026-11-06 07:26:10');
/*!40000 ALTER TABLE `cms_sections` ENABLE KEYS */;
UNLOCK TABLES;

