INSERT INTO `destination_faqs` VALUES (1,123,'Best Time to Visit Chennai & Tamil Nadu','Tamil Nadu can be explored throughout the year, but the most pleasant season is from October to March, when the climate is ideal for temple visits, heritage walks, hill stations, and coastal sightseeing.',1,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(2,123,'Comfortable Private Sightseeing','Discover Tamil Nadu in comfort with private, air-conditioned transportation and a dedicated chauffeur guide, allowing flexible itineraries across cities, temples, hill stations, and coastal destinations at your own pace.',2,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(3,123,'Cultural & Heritage Experiences','Experience the soul of South India through ancient temples, UNESCO heritage sites, classical arts, traditional villages, spiritual centers, and vibrant local festivals that reflect Tamil Nadu’s timeless identity.',3,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(4,123,'Flexible Tour Across All Seasons','Tamil Nadu tours are available year-round, with itineraries customized to suit seasonal conditions, festival calendars, and traveler preferences—perfect for families, pilgrims, culture lovers, and explorers alike.',4,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(5,122,'Best Time to Visit Kerala','The ideal season to explore Kerala is between September and March for cool pleasant backwater cruises, and June to August for authentic monsoon Ayurvedic wellness therapies.',1,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(6,122,'Private Houseboat & Chauffeur Safaris','Sail along serene backwaters in luxury air-conditioned houseboats with private chef and dedicated guide, complemented by private transfers across tea estates and coastal sanctuaries.',2,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(7,122,'Spice Trails & Wildlife Safaris','Walk through fragrant cardamom, pepper, and vanilla plantations in Thekkady, and cruise Lake Periyar to view wild elephants, exotic birds, and tropical flora in their natural habitat.',3,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(8,122,'Holistic Ayurveda & Classical Arts','Experience time-honored Ayurvedic rejuvenation treatments, witness dramatic Kathakali dance performances, and discover Kalaripayattu martial art demonstrations.',4,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(9,121,'Best Time to Visit Karnataka','October to April provides cool, sunny weather perfect for exploring the rock-cut monuments of Hampi, Mysore Palace festivities, and wildlife safaris.',1,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(10,121,'Royal Heritage & Architectural Wonders','Marvel at the illuminated Mysore Palace, explore the boulder-strewn ruins of the UNESCO Vijayanagara Empire in Hampi, and study the intricate Hoysala temple carvings.',2,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(11,121,'Coffee Plantations & Nature Escapes','Immerse yourself in lush coffee and spice estates in Coorg and Chikmagalur, staying in luxury plantation bungalows with private nature walks.',3,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(12,121,'Wildlife Safaris & Nature Sanctuaries','Embark on private guided Jeep safaris in Kabini and Bandipur Tiger Reserve to encounter wild Bengal tigers, leopards, and herds of Asian elephants.',4,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(13,120,'Best Time to Visit Goa','November to March is the peak season with sunny skies, warm tropical waters, and vibrant seaside cafe culture.',1,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(14,120,'Old Goa & UNESCO Baroque Churches','Visit the Basilica of Bom Jesus and Se Cathedral, showcasing magnificent 16th-century Portuguese architecture and sacred art.',2,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(15,120,'Spice Plantations & Mandovi River Cruises','Take an aromatic walking tour through organic spice plantations followed by private sunset cruises along the Mandovi River.',3,'published','2026-09-28 15:23:23','2026-09-28 15:23:23'),(16,120,'Private Chauffeur Coastal Explorations','Travel in sanitized luxury private vehicles to explore hidden beaches in South Goa, historic forts like Fort Aguada and Chapora, and traditional Latin Quarter villas.',4,'published','2026-09-28 15:23:23','2026-09-28 15:23:23');
/*!40000 ALTER TABLE `destination_faqs` ENABLE KEYS */;
UNLOCK TABLES;

