INSERT INTO `destination_sections` VALUES (1,123,'seasonal_activities','Best Time to Visit Tamil Nadu',NULL,'Tamil Nadu can be explored throughout the year, but the most pleasant season is from October to March, when the climate is ideal for temple visits, heritage walks, hill stations, and coastal sightseeing.',408,1,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(2,123,'seasonal_activities','Comfortable Private Sightseeing',NULL,'Explore Tamil Nadu comfortably with private, chauffeur-driven vehicles designed for flexible sightseeing across temples, heritage landmarks, cities, hill stations, and coastal destinations.',428,2,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(3,123,'seasonal_activities','Cultural & Heritage Experiences',NULL,'Experience Tamil Nadu through its magnificent temples, UNESCO heritage landmarks, classical Tamil culture, Bharatanatyam, Carnatic music, traditional cuisine, silk weaving, and historic architecture.',433,3,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(4,123,'seasonal_activities','Flexible Tours Across All Seasons',NULL,'Tamil Nadu offers flexible travel experiences throughout the year, allowing travelers to combine cultural heritage, temple visits, beaches, hill stations, wildlife, and local experiences according to the season.',418,4,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(5,122,'seasonal_activities','Best Time to Visit Kerala',NULL,'The ideal season to explore Kerala is between September and March for cool, pleasant backwater cruises and sightseeing, while June to August offers the best climate for traditional Ayurvedic wellness therapies and lush monsoon landscapes.',369,1,'active','2026-09-29 08:07:58','2026-09-29 08:07:58'),(6,122,'seasonal_activities','Comfortable Private Sightseeing',NULL,'Travel effortlessly across Kerala in private, air-conditioned chauffeur-driven vehicles with dedicated local driver-guides, providing seamless transfers between Kochi, Munnar, Thekkady, Alleppey, and Kovalam.',377,2,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(7,122,'seasonal_activities','Backwaters & Nature Experiences',NULL,'Cruise along tranquil palm-fringed backwaters aboard authentic luxury houseboats in Alleppey and Kumarakom, walk through fragrant tea and spice plantations in Munnar, and explore Periyar Lake wildlife sanctuaries.',382,3,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(8,122,'seasonal_activities','Cultural & Heritage Experiences',NULL,'Immerse yourself in Kerala’s rich living heritage with live Kathakali dance dramas, Kalaripayattu martial arts, historic colonial architecture in Fort Kochi, and vibrant temple festivals.',370,4,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(9,122,'seasonal_activities','Flexible Tours Across All Seasons',NULL,'Kerala tours are customizable for every season, offering relaxing backwater retreats, high-altitude hill station escapes, tropical beach getaways, and holistic Ayurvedic rejuvenation all year round.',392,5,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(10,121,'seasonal_activities','Best Time to Visit Karnataka',NULL,'October to April provides the most pleasant and dry weather for exploring the UNESCO ruins of Hampi, the regal palaces of Mysore, wildlife safaris, and the cool coffee hills of Coorg.',348,1,'active','2026-09-29 08:07:58','2026-09-29 08:07:58'),(11,121,'seasonal_activities','Comfortable Private Sightseeing',NULL,'Discover Karnataka with private sanitized chauffeur-driven vehicles, ensuring comfortable travel across historic temple circuits, royal heritage cities, wildlife reserves, and scenic Western Ghats destinations.',355,2,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(12,121,'seasonal_activities','Heritage & Historical Experiences',NULL,'Marvel at the illuminated grandeur of Mysore Palace, walk through the ancient boulder-strewn monuments of the Vijayanagara Empire in Hampi, and admire the stone carvings of Belur and Halebidu.',333,3,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(13,121,'seasonal_activities','Nature & Wildlife Experiences',NULL,'Embark on thrilling Jeep safaris in Nagarhole and Bandipur National Parks to spot wild tigers and Asian elephants, and stay in serene coffee estate homestays amidst the misty hills of Coorg and Chikmagalur.',338,4,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(14,121,'seasonal_activities','Flexible Tours Across All Seasons',NULL,'Karnataka offers varied travel experiences in every season, from winter heritage tours and wildlife expeditions to lush monsoon waterfall journeys and year-round coffee plantation retreats.',360,5,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(15,120,'seasonal_activities','Best Time to Visit Goa',NULL,'November to March is the peak season with sunny tropical skies, warm waters, and vibrant beach shacks, while June to September offers lush green landscapes and tranquil romantic monsoon getaways.',279,1,'active','2026-09-29 08:07:58','2026-09-29 08:07:58'),(16,120,'seasonal_activities','Comfortable Private Sightseeing',NULL,'Explore North and South Goa in comfort with private air-conditioned vehicles, tailored for hassle-free sightseeing across historic forts, pristine beaches, spice plantations, and Portuguese quarters.',284,2,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(17,120,'seasonal_activities','Beaches & Coastal Experiences',NULL,'Relax on sun-kissed golden sand beaches from lively Baga and Calangute to serene South Goa havens like Palolem and Morjim, enjoy thrilling watersports, and take sunset cruises along the Mandovi River.',273,3,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(18,120,'seasonal_activities','Cultural & Heritage Experiences',NULL,'Discover Goa’s rich Indo-Portuguese heritage with visits to the UNESCO Baroque churches of Old Goa including Basilica of Bom Jesus and Se Cathedral, historic Fort Aguada, and the colorful Latin Quarter of Fontainhas.',295,4,'active','2026-09-29 08:07:58','2026-09-29 10:10:56'),(19,120,'seasonal_activities','Flexible Tours Across All Seasons',NULL,'Goa offers versatile travel opportunities throughout the year, from vibrant winter beach holidays and heritage sightseeing to peaceful off-season wellness retreats and spice plantation excursions.',282,5,'active','2026-09-29 08:07:58','2026-11-14 03:47:37');
/*!40000 ALTER TABLE `destination_sections` ENABLE KEYS */;
