INSERT INTO `destinations` VALUES (120,'Goa','goa','Goa','Discover Goa with our tours.','Discover Goa with our tours. Sun-kissed beaches, UNESCO Portuguese cathedrals, spice plantations, and serene river cruises.','Golden Beaches, Baroque Cathedrals & Vibrant Coastlines','Sun, Sand, Spice & Portuguese Heritage','Goa is India’s most celebrated coastal haven, blessed with sun-drenched Arabian Sea beaches, UNESCO World Heritage Baroque churches of Old Goa, spice plantations, and historic Portuguese mansions.\n\nOffering a unique fusion of Indian hospitality and European charm, Goa provides unforgettable beachside relaxation, heritage walks, river cruises, and flavorful coastal dining.',283,'English / Konkani','Indian Rupee (INR)','Christianity / Hinduism','Portuguese & Coastal Heritage','GMT +5:30',NULL,NULL,316,NULL,NULL,NULL,1,4,'published','2026-09-26 06:13:02','2026-09-29 10:10:56',NULL,NULL),(121,'Karnataka','karnataka','Karnataka','Discover Karnataka with our tours.','Discover Karnataka with our tours. Regal palaces of Mysore, UNESCO ruins of Hampi, lush coffee estates in Coorg, and rich wildlife sanctuaries.','Royal Palaces, Ancient Hampi & Coffee Mist Hills','One State, Many Worlds','Karnataka is a mesmerizing land of royal opulence and UNESCO architectural treasures. Home to the legendary Vijayanagara Empire capital of Hampi, the stone-carved temples of Belur and Halebidu, the regal Mysore Palace, and aromatic coffee hills of Coorg and Chikmagalur.\n\nKarnataka seamlessly bridges historic grandeur with lush wildlife national parks and vibrant cultural life. Experience royal heritage, wildlife safaris in Bandipur and Nagarhole, and breathtaking waterfalls cascading down the Western Ghats.',349,'English / Kannada','Indian Rupee (INR)','Hinduism / Christianity / Islam / Jainism','Hampi / Mysore / Historic Heritage','GMT +5:30',NULL,NULL,318,NULL,NULL,NULL,1,3,'published','2026-09-26 06:13:02','2026-09-29 10:10:56',NULL,NULL),(122,'Kerala','kerala','Kerala','Discover Kerala with our tours.','Discover Kerala with our tours. Tranquil emerald backwaters, tea plantation hills in Munnar, Ayurvedic wellness, and tropical beaches.','Enchanting Palm Groves, Spice Hills & Serene Waters','God’s Own Country — Nature, Backwaters & Wellness','Kerala is a tropical paradise acclaimed worldwide for its tranquil emerald backwaters, misty Western Ghat hill stations, pristine Arabian Sea coastlines, and ancient Ayurvedic healing traditions.\n\nFlourishing through centuries of spice trade with Arab, Roman, and European mariners, Kerala offers an exquisite tapestry of Kathakali dance, temple festivals, tea plantations, and backwater houseboats. From the rolling hills of Munnar to the palm-fringed canals of Alleppey and the vibrant spice markets of Fort Kochi, Kerala offers a serene rejuvenation of mind, body, and soul.',376,'English / Malayalam','Indian Rupee (INR)','Hinduism / Christianity / Islam','Backwaters / Western Ghats / Cultural Heritage','GMT +5:30',NULL,NULL,319,NULL,NULL,NULL,1,2,'published','2026-09-26 06:13:02','2026-09-29 10:10:56',NULL,NULL),(123,'Tamil Nadu','tamil-nadu','Tamil Nadu','Discover Tamil Nadu with our tours.','Discover Tamil Nadu with our tours. Explore ancient Dravidian temples, UNESCO heritage monuments, hill stations, and vibrant cultural arts.','History of the Land of Temples & Timeless Culture','Tamil Nadu is ancient, Tamil Nadu is eternal','Tamil Nadu is one of the world’s oldest living civilizations, with a history that stretches back over 5,000 years. Renowned for its classical heritage, the region flourished under powerful dynasties such as the Cholas, Cheras, Pandyas, Pallavas, and Vijayanagara rulers, who shaped South India through monumental architecture, literature, trade, and spiritual traditions.\n\nThe state is celebrated as the Land of Temples, home to magnificent Dravidian marvels like Brihadeeswarar Temple, Meenakshi Amman Temple, Shore Temple, and Ekambareswarar Temple. Beyond architecture, Tamil Nadu is the birthplace of Tamil language, one of the oldest classical languages in the world, and a vibrant center for Bharatanatyam, Carnatic music, silk weaving, bronze sculptures, and spiritual philosophy. Today, Tamil Nadu seamlessly blends ancient traditions with modern life, offering travelers a deeply enriching cultural journey.',282,'English / Tamil','Indian Rupee (INR)','Hinduism / Christianity / Islam','UNESCO World Heritage Sites','GMT +5:30',NULL,NULL,427,NULL,NULL,NULL,1,1,'published','2026-09-26 06:13:02','2026-11-14 03:47:38',NULL,NULL);
/*!40000 ALTER TABLE `destinations` ENABLE KEYS */;
