INSERT INTO `home_hero_slides` VALUES (37,'Dream. Travel. Discover.',NULL,485,485,'Explore Tours','/tours',2,NULL,NULL,'inactive','2026-09-29 10:12:41',1,'2026-09-28 05:59:36','2026-09-29 10:12:41'),(38,'Kerala Emerald Backwaters & Wellness','Cruise tranquil palm-fringed backwaters, misty tea plantations, and rejuvenate with Ayurveda.',266,266,'Explore Tours','/tours',2,NULL,NULL,'active',NULL,NULL,'2026-09-28 05:59:36','2026-11-03 07:08:23'),(39,'Karnataka Royal Palaces & UNESCO Hampi','Discover the golden grandeur of Mysore Palace, ancient ruins of Hampi, and lush coffee hills.',265,265,'Explore Tours','/tours',3,NULL,NULL,'active',NULL,NULL,'2026-09-28 05:59:36','2026-11-03 07:08:23'),(40,'Goa Golden Beaches & Coastal Splendor','Relax on sun-kissed coastlines, historic Portuguese heritage sites, and vibrant culture.',264,264,'Explore Tours','/tours',4,NULL,NULL,'active','2026-11-03 07:08:23',458,'2026-09-28 05:59:36','2026-11-03 07:08:23'),(41,'Tamil Nadu Living Heritage & Grand Temples','Explore magnificent Dravidian temples, UNESCO monuments, and timeless classical arts.',270,270,'Explore Tours','/tours',1,NULL,NULL,'active',NULL,NULL,'2026-09-28 05:59:36','2026-11-03 07:08:23'),(42,'Taj Mahal & Iconic Wonders',NULL,269,269,'Explore Tours','/tours',8,NULL,NULL,'inactive','2026-09-29 10:12:41',1,'2026-09-28 05:59:36','2026-09-29 10:12:41'),(43,'Rajasthan Royal Forts & Desert Safaris',NULL,268,268,'Explore Tours','/tours',7,NULL,NULL,'inactive','2026-09-29 10:12:41',1,'2026-09-28 05:59:36','2026-09-29 10:12:41'),(44,'Delhi Historic Heart & Cultural Monuments',NULL,263,263,'Explore Tours','/tours',8,NULL,NULL,'inactive','2026-09-29 10:12:41',1,'2026-09-28 05:59:36','2026-09-29 10:12:41'),(45,'Munnar Misty Tea Plantations',NULL,381,381,'Explore Tours','/tours',9,NULL,NULL,'inactive','2026-09-29 10:12:41',1,'2026-09-28 05:59:36','2026-09-29 10:12:41'),(48,'New Spectacular Journey','Experience breathtaking vistas and curated private safaris with Wonderer South India.