  `description` text COLLATE utf8mb4_unicode_ci,
  `evaluation_details` text COLLATE utf8mb4_unicode_ci,
  `report_information` text COLLATE utf8mb4_unicode_ci,
  `display_order` int NOT NULL DEFAULT '0',
