  PRIMARY KEY (`id`),
  KEY `idx_assessment_order` (`assessment_id`,`display_order`),
  CONSTRAINT `medical_assessment_tests_ibfk_1` FOREIGN KEY (`assessment_id`) REFERENCES `medical_assessments` (`id`) ON DELETE CASCADE
