INSERT INTO `medical_assessment_tests` VALUES (1,1,'Whole Body Neuro & Spinal MRI','High-field axial and sagittal imaging of cerebral tissue, ventricular system, and spinal column.','Evaluates brain microvascular changes, silent infarctions, disc herniations, and spinal canal stenosis.','Multi-slice DICOM imaging archive and Radiologist diagnostic report.',1,'2026-10-30 09:24:28','2026-10-30 09:24:28'),(2,1,'Abdominal & Pelvic Organ MR Screening','Contrast-free organ parenchymal sequence evaluating abdominal viscus.','Detects organomegaly, focal lesions, renal cysts, and occult retroperitoneal pathology.','Cross-sectional volumetric assessment and organ health summary.',2,'2026-10-30 09:24:28','2026-10-30 09:24:28'),(3,2,'Bone Mineral Density (BMD) T-Score & Z-Score','Dual-energy radiologic assessment of axial skeleton bone matrix mineralization.','Screening for osteopenia, osteoporosis, and age-adjusted fracture risk prediction.','Full BMD T-score chart, WHO diagnostic categorization, and 10-year fracture risk index.',1,'2026-10-30 09:24:28','2026-10-30 09:24:28'),(4,2,'Segmental Body Composition & Visceral Fat Profiling','Total body dual-energy scan differentiating android vs gynoid fat distribution and lean muscle mass.','Assesses visceral adipose tissue associated with cardiovascular risk and sarcopenia.','Total fat percentage, visceral fat volume (cm³), and regional muscle mass balance.',2,'2026-10-30 09:24:28','2026-10-30 09:24:28'),(5,3,'Advanced Cardiovascular & Lipid Subfractions','Lipid fractionation including ApoB, Lp(a), hs-CRP, Total Cholesterol, HDL, LDL, and Triglycerides.','Evaluates vascular endothelial inflammation, atherogenic particle concentration, and long-term coronary risk.','Complete lipid panel with atherogenic index and cardiovascular risk score.',1,'2026-10-30 09:24:28','2026-10-30 09:24:28'),(6,3,'Comprehensive Metabolic & Organ Profile','Hepatic enzymes (ALT, AST, ALP, GGT), renal markers (Creatinine, eGFR, BUN), fasting glucose, and HbA1c.','Detects insulin resistance, early non-alcoholic fatty liver changes, and renal filtration efficiency.','Organ functional profiling with comparative reference ranges.',2,'2026-10-30 09:24:28','2026-10-30 09:24:28'),(7,4,'Breath-by-Breath Spiroergometry CPET','Gas exchange analysis with continuous 12-lead ECG monitoring under incremental physical workload.','Identifies true physiological aerobic capacity and rules out exercise-induced ischemia or arrhythmias.','VO₂ Max percentile classification, ventilatory thresholds, and cardio-respiratory fitness score.',1,'2026-10-30 09:24:28','2026-10-30 09:24:28'),(8,5,'Isometric Peak Force & Bilateral Symmetry Analysis','Multi-joint load cell dynamometry evaluating muscular power and agonist/antagonist force ratios.','Detects hidden musculoskeletal imbalances that lead to joint degradation, lower back pain, or sports injury.','Segmental strength distribution graph and corrective exercise recommendations.',1,'2026-10-30 09:24:28','2026-10-30 09:24:28'),(9,6,'Indirect Calorimetry Breath Analysis','Measurement of resting oxygen uptake with dilution canopy or calibrated mask under steady-state baseline rest.','Calculates exact individual resting calorie requirements to identify metabolic slowing or hypermetabolism.','Measured RMR vs predicted Harris-Benedict value and personalized caloric intake blueprint.',1,'2026-10-30 09:24:28','2026-10-30 09:24:28');
/*!40000 ALTER TABLE `medical_assessment_tests` ENABLE KEYS */;
UNLOCK TABLES;

