INSERT INTO `medical_assessments` VALUES (1,1,'Full Body MRI','Structural Assessment','Provides detailed images of your organs, tissues, bones and joints to detect structural abnormalities and early signs of disease.','High-resolution magnetic resonance imaging across brain, spine, thorax, abdomen, and pelvis utilizing cutting-edge non-invasive 3-Tesla MRI technology without radiation exposure.','/uploads/media/medical_full_body_mri.jpg','Scan','Brain parenchyma, cervical/lumbar spine, liver, kidneys, pancreas, spleen, pelvic organs, major arterial vasculature, and musculoskeletal junctions.',1,1,'2026-10-30 09:24:28','2026-11-05 08:04:02'),(2,1,'DEXA Scan','Body Composition & Bone Density','Measures bone mineral density and body composition to assess bone health, muscle mass and fat distribution.','Dual-energy X-ray absorptiometry providing the clinical gold standard in bone mineral densitometry and segmental body fat quantification.','/uploads/media/medical_dexa_scan.jpg','Bone','Lumbar spine (L1-L4), bilateral femoral neck, total body fat percentage, visceral adipose tissue (VAT), and appendicular lean mass.',2,1,'2026-10-30 09:24:28','2026-11-05 07:12:02'),(3,1,'Blood Pro','120+ Blood Biomarkers','Comprehensive blood analysis of 120+ biomarkers to assess your overall health, organ function, metabolic health and more.','Exhaustive venous blood panel evaluating glycemic control, advanced lipid sub-fractions, liver and kidney function, thyroid endocrinology, hematology, and micronutrient status.','/uploads/media/medical_blood_pro.jpg','Droplet','Complete Blood Count (CBC), Complete Metabolic Panel, High-Sensitivity CRP, Apolipoprotein B, HbA1c, Liver Function Panel, Kidney Function Panel, Thyroid Panel (TSH, FT3, FT4), Vitamin D & B12, and Electrolytes.',3,1,'2026-10-30 09:24:28','2026-11-05 08:04:02'),(4,1,'VO₂ Max Test','Aerobic Performance','Measures your maximum oxygen uptake to evaluate cardiovascular fitness and endurance capacity.','Cardiopulmonary exercise testing (CPET) measuring breath-by-breath oxygen consumption (VO₂) and carbon dioxide exhalation (VCO₂) during a graded treadmill protocol.','/uploads/media/medical_vo2_max.jpg','Activity','Peak oxygen consumption (ml/kg/min), ventilatory anaerobic threshold (VT1 & VT2), maximum heart rate, and aerobic endurance capacity.',4,1,'2026-10-30 09:24:28','2026-11-05 08:04:02'),(5,1,'Strength Pro Assessment','Musculoskeletal Strength','Evaluates your muscular strength, balance, flexibility and functional movement for better performance and injury prevention.','Computerized dynamometry and functional movement analysis measuring isometric muscle strength, bilateral symmetry, postural stability, and joint range of motion.','/uploads/media/medical_strength_pro.jpg','Dumbbell','Upper and lower body peak torque, limb asymmetry indices, core endurance, and functional mobility screens.',5,1,'2026-10-30 09:24:28','2026-11-05 07:12:02'),(6,1,'Resting Metabolic Rate (RMR)','Metabolic Function','Measures the number of calories your body burns at rest to help plan your nutrition, fitness and weight management goals.','Indirect calorimetry measurement under thermal neutral resting conditions determining baseline resting energy expenditure (REE) and substrate oxidation ratios.','/uploads/media/medical_rmr_metabolic.jpg','Flame','Daily basal caloric expenditure (kcal/day), respiratory quotient (RQ), and carbohydrate vs fat metabolic fuel utilization.',6,1,'2026-10-30 09:24:28','2026-11-05 07:12:02');
/*!40000 ALTER TABLE `medical_assessments` ENABLE KEYS */;
UNLOCK TABLES;

