INSERT INTO `medical_trips` VALUES (1,'APEX Comprehensive Health Check','apex-comprehensive-health-check','Executive Health Check','The APEX Comprehensive Health Check is a premium medical tourism package designed to give you a complete picture of your health. With advanced diagnostics and expert care, you can travel with confidence and focus on what matters most - your well-being.','Experience world-class healthcare combined with the serenity of South India. The APEX Comprehensive Health Check offers unparalleled health screening using cutting-edge medical technologies, including 3T Full Body MRI, DEXA bone densitometry, comprehensive metabolic profiling, and advanced cardiopulmonary exercise testing. Accompanied by experienced medical specialists, you receive detailed, actionable health insights in a seamless 1-day executive setting.','1 Day',20000.00,NULL,'INR','Chennai, Tamil Nadu','/uploads/media/medical_package_banner.jpg','APEX Comprehensive Health Check','A Complete Health Assessment for a Healthier Tomorrow.','The APEX Comprehensive Health Check is a premium medical tourism package designed to give you a complete picture of your health. With advanced diagnostics and expert care, you can travel with confidence and focus on what matters most - your well-being.','/uploads/media/medical_package_banner.jpg','[\"Complete 3T Full Body MRI Structural Scan\",\"Gold Standard DEXA Bone Density & Visceral Fat Profiling\",\"120+ Biomarkers Comprehensive Blood Profile\",\"Clinical VO\\u2082 Max Aerobic Capacity Testing\",\"Functional Musculoskeletal & Strength Evaluation\",\"Precision Resting Metabolic Rate (RMR) Analysis\",\"One-on-One Consultant Physician Consultation\",\"Dedicated Medical Tourism Concierge & Transfers\"]','[\"Early risk detection of silent cardiovascular and metabolic disorders\",\"Complete body composition profiling for fitness and longevity\",\"Personalized lifestyle, nutrition, and preventive medical guidance\",\"Same-day consolidated digital health records and physician debrief\"]','Fasting for 10-12 hours prior to blood tests is mandatory. Wear comfortable sportswear for the VO₂ Max and Strength assessments. Avoid caffeine and strenuous physical exercise for 24 hours prior to metabolic and RMR testing.','Please carry your past medical records, prescription medications, and valid identification. Arrive at the wellness diagnostic facility by 7:30 AM on your scheduled date.','[\"All 6 Specialized Medical Assessments & Imaging\",\"Comprehensive Laboratory Diagnostics (120+ Biomarkers)\",\"Detailed Physician Consultation & Multidisciplinary Review\",\"Personalized Health Risk & Preventive Action Plan\",\"Executive Lounge Access, Light Breakfast & Lunch\",\"Private Hotel to Diagnostic Center Transfers\"]','[\"Flights and visa processing fees\",\"Follow-up surgical or tertiary treatments if required\",\"Personal medication prescriptions post-checkup\"]','Free cancellation or rescheduling up to 48 hours prior to the scheduled examination appointment. 50% cancellation fee within 24 to 48 hours. Non-refundable for same-day no-shows.',1,1,'2026-10-30 09:24:28','2026-11-11 05:43:11');
/*!40000 ALTER TABLE `medical_trips` ENABLE KEYS */;
UNLOCK TABLES;

