INSERT INTO `pages` VALUES (1,'about-us','About Wonderer South India','Your Trusted Travel Partner for Authentic South Indian Experiences',NULL,'<h2>Welcome to Wonderer South India</h2><p>Wonderer South India is dedicated to providing high-quality, reliable, and personalized travel experiences across South India for international and discerning travelers. With years of local expertise, private luxury vehicle fleets, and expert guides, we turn vacations into unforgettable journeys.</p><h3>Our Mission</h3><p>To deliver authentic, safe, comfortable, and seamless travel memories with transparent pricing and exceptional hospitality.</p>','About Us | Wonderer South India','Learn about Wonderer South India, our commitment to hospitality, private travel expertise, and memorable South Indian experiences.','published',NULL,NULL,'2026-09-24 10:54:48','2026-09-30 04:46:16'),(2,'terms-conditions','Terms & Conditions','Official service agreement, booking policies, guest responsibilities, and legal guidelines for Tramax Tours.',NULL,'<div class=\"terms-container-v2\">\n  <div class=\"terms-intro-box\">\n    <p class=\"terms-lead\">Welcome to <strong>Wonderer South India</strong>.</p>\n    <p>By accessing or using our website and services, you agree to comply with and be bound by the following Terms & Conditions. Please read them carefully before using our services.</p>\n  </div>\n\n  <section id=\"acceptance\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">01</span>\n      <h3 class=\"terms-sec-title\">Acceptance of Terms</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>By visiting this website, submitting an enquiry, or booking any service with Wonderer South India, you acknowledge that you have read, understood, and agreed to these Terms & Conditions. If you do not agree, please do not use our website or services.</p>\n    </div>\n  </section>\n\n  <section id=\"services\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">02</span>\n      <h3 class=\"terms-sec-title\">Services Offered</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>Wonderer South India provides travel-related services including but not limited to:</p>\n      <ul class=\"terms-list\">\n        <li><strong>Tour packages:</strong> Curated multi-day journeys, day tours, and private heritage circuits.</li>\n        <li><strong>Hotel bookings:</strong> Verified luxury resorts, heritage stays, and boutique hotels.</li>\n        <li><strong>Transportation arrangements:</strong> Private AC chauffeur-driven sedans, SUVs, and luxury coaches.</li>\n        <li><strong>Ticket booking:</strong> Flight, train, bus, and entry monument passes.</li>\n        <li><strong>Travel guides:</strong> Certified multilingual tourist guides and local cultural experts.</li>\n        <li><strong>Passport & Visa assistance:</strong> Comprehensive document guidance and facilitation.</li>\n        <li><strong>Photography services:</strong> Professional vacation photography and video documentation.</li>\n      </ul>\n      <p class=\"terms-note\"><em>Note: All services are subject to real-time availability and confirmation.</em></p>\n    </div>\n  </section>\n\n  <section id=\"booking-payments\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">03</span>\n      <h3 class=\"terms-sec-title\">Booking & Payments</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <ul class=\"terms-list\">\n        <li>All bookings are confirmed only after receipt of the required advance payment.</li>\n        <li>Payment terms may vary depending on the service or package selected.</li>\n        <li>Prices mentioned on the website are subject to change without prior notice based on seasonal tariffs.</li>\n        <li>Any additional charges (taxes, entry fees, personal expenses, toll/parking, etc.) are not included unless explicitly mentioned in your confirmed itinerary.</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"cancellations-refunds\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">04</span>\n      <h3 class=\"terms-sec-title\">Cancellations & Refunds</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <ul class=\"terms-list\">\n        <li>Cancellation requests must be made in writing via official email or our verified contact form.</li>\n        <li>Refund eligibility depends strictly on the cancellation policies of partner hotels, transport providers, airlines, and third-party vendors.</li>\n        <li>Wonderer South India shall not be responsible for delays in refunds caused by third-party service providers or banking gateways.</li>\n        <li>No refunds will be provided for unused services or last-minute cancellations during peak travel seasons.</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"changes-modifications\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">05</span>\n      <h3 class=\"terms-sec-title\">Changes & Modifications</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>Wonderer South India reserves the right to modify itineraries, services, or pricing due to unavoidable circumstances such as adverse weather conditions, natural calamities, government regulations, road blockages, or operational safety issues.</p>\n      <p>Any changes will be communicated to the customer at the earliest possible time with suitable alternatives offered wherever viable.</p>\n    </div>\n  </section>\n\n  <section id=\"user-responsibilities\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">06</span>\n      <h3 class=\"terms-sec-title\">User Responsibilities</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <ul class=\"terms-list\">\n        <li>Users must provide accurate, current, and complete personal, travel, and contact information.</li>\n        <li>Travelers are solely responsible for carrying valid government-issued identity proofs, passports, visas, and other required health or travel documents.</li>\n        <li>Wonderer South India will not be liable for any issues, delays, or denials arising due to incorrect, expired, or incomplete information provided by the user.</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"risks-liability\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">07</span>\n      <h3 class=\"terms-sec-title\">Travel Risks & Liability</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>Travel involves inherent risks. Wonderer South India shall not be held responsible for accidents, injuries, illnesses, loss of personal belongings, delays, or cancellations caused by factors beyond our reasonable control (force majeure).</p>\n      <p>We act primarily as a professional coordinator and intermediary between customers and verified third-party service providers and are not directly liable for their independent acts, omissions, or defaults.</p>\n    </div>\n  </section>\n\n  <section id=\"intellectual-property\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">08</span>\n      <h3 class=\"terms-sec-title\">Intellectual Property</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>All content on this website including text, photography, graphics, logos, itineraries, and UI designs are the intellectual property of Wonderer South India.</p>\n      <p>Unauthorized copying, scraping, reproduction, or commercial distribution of website content is strictly prohibited without prior written consent.</p>\n    </div>\n  </section>\n\n  <section id=\"privacy\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">09</span>\n      <h3 class=\"terms-sec-title\">Privacy</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>Any personal information shared with us is handled with high confidentiality in accordance with our Privacy Policy.</p>\n      <p>We do not sell, rent, or misuse customer data and implement rigorous technical measures to safeguard your personal information.</p>\n    </div>\n  </section>\n\n  <section id=\"third-party-links\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">10</span>\n      <h3 class=\"terms-sec-title\">Third-Party Links</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>Our website may contain links to external third-party websites or services. Wonderer South India does not control and is not responsible for the content, privacy policies, or practices of such external sites.</p>\n    </div>\n  </section>\n\n  <section id=\"governing-law\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">11</span>\n      <h3 class=\"terms-sec-title\">Governing Law</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>These Terms & Conditions shall be governed by and interpreted in accordance with the laws of the Republic of India. Any legal disputes or claims arising hereunder shall be subject to the exclusive jurisdiction of the competent courts in Tamil Nadu, India.</p>\n    </div>\n  </section>\n\n  <section id=\"updates-terms\" class=\"terms-section-card\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">12</span>\n      <h3 class=\"terms-sec-title\">Updates to Terms</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>Wonderer South India reserves the right to update or modify these Terms & Conditions at any time without prior notice. Continued use of the website or booking of services constitutes acceptance of the updated terms.</p>\n    </div>\n  </section>\n\n  <section id=\"contact-info\" class=\"terms-section-card terms-contact-highlight\">\n    <div class=\"terms-sec-header\">\n      <span class=\"terms-sec-num\">13</span>\n      <h3 class=\"terms-sec-title\">Contact Information</h3>\n    </div>\n    <div class=\"terms-sec-body\">\n      <p>For any questions, clarifications, or support regarding these Terms & Conditions, please reach out to us:</p>\n      <div class=\"terms-contact-grid\">\n        <div class=\"terms-contact-item\">\n          <strong>📧 Email:</strong> <a href=\"mailto:contact@tramaxtours.in\">contact@tramaxtours.in</a> / <a href=\"mailto:info@tramaxtours.in\">info@tramaxtours.in</a>\n        </div>\n        <div class=\"terms-contact-item\">\n          <strong>📞 Phone:</strong> <a href=\"tel:+918072566010\">+91 80725 66010</a> / <a href=\"tel:+919840291110\">+91 98402 91110</a>\n        </div>\n        <div class=\"terms-contact-item\">\n          <strong>📍 Office:</strong> Chennai, Tamil Nadu, India\n        </div>\n      </div>\n    </div>\n  </section>\n</div>','Terms & Conditions | Wonderer South India','Read the official Terms & Conditions for Wonderer South India. Learn about booking rules, cancellations, refunds, services, and travel responsibilities.','published',NULL,NULL,'2026-09-24 10:54:48','2026-11-11 05:18:01'),(3,'refund-policy','Refund & Cancellation Policy','Transparent terms for booking confirmations, cancellation procedures, refund eligibility, timelines, and tour rescheduling.',NULL,'<div class=\"policy-container-v2 refund-policy-theme\">\n  <div class=\"policy-intro-box refund-banner-gradient\">\n    <p class=\"policy-lead\">At <strong>Wonderer South India</strong>, we understand that travel plans may change unexpectedly.</p>\n    <p>This Refund & Cancellation Policy outlines the exact terms under which cancellations, refunds, and rescheduling are handled. Please review this policy carefully before confirming your reservations.</p>\n  </div>\n\n  <section id=\"booking-confirmation\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">01</span>\n      <h3 class=\"policy-sec-title\">Booking Confirmation & Advance Payment</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <ul class=\"policy-list\">\n        <li>All tour packages and travel bookings are officially confirmed only after receipt of the required advance payment.</li>\n        <li>Official booking confirmation vouchers will be dispatched via email or WhatsApp containing complete itinerary specifics.</li>\n        <li>Any service, entrance pass, or detour not explicitly mentioned in the confirmed itinerary voucher will be treated as an additional chargeable service.</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"cancellation-procedure\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">02</span>\n      <h3 class=\"policy-sec-title\">Cancellation Policy & Notification</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <ul class=\"policy-list\">\n        <li>All cancellation requests must be submitted in writing via official email to <strong>contact@tramaxtours.in</strong> or through our verified <strong>Contact Us</strong> page.</li>\n        <li>The timestamp on which the written cancellation request is officially received will be registered as the official cancellation date.</li>\n        <li>Cancellation charges vary according to provider deadlines (partner hotels, airlines, heritage transport operators, etc.).</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"refund-eligibility\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">03</span>\n      <h3 class=\"policy-sec-title\">Refund Eligibility & Conditions</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>Refunds, if applicable, are subject to the individual terms and contractual cancellation policies of our third-party service partners. Wonderer South India acts as a professional intermediary and coordinates with vendors to maximize refund recovery.</p>\n      \n      <div class=\"policy-sub-card policy-eligible-box\">\n        <h4 class=\"policy-sub-title\" style=\"color: #01806c;\">✅ Refunds May Be Applicable Under:</h4>\n        <ul class=\"policy-list\">\n          <li>Cancellations submitted within the permitted advance time frame as stipulated in your specific package voucher.</li>\n          <li>Non-availability or cancellation of a confirmed service due to internal reasons beyond the customer\'s control.</li>\n          <li>Verified duplicate transactions or overpayments (reimbursed in full after audit).</li>\n        </ul>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"non-refundable\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num policy-sec-num-alert\">04</span>\n      <h3 class=\"policy-sec-title\">Non-Refundable Situations</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <div class=\"policy-warning-card\">\n        <h4 class=\"policy-sub-title\" style=\"color: #b91c1c;\">⚠️ Strictly Non-Refundable Cases:</h4>\n        <ul class=\"policy-list policy-list-alert\">\n          <li>Last-minute cancellations or guest no-shows on the departure date.</li>\n          <li>Partial utilization or voluntary abandonment of booked tour components.</li>\n          <li>Cancellations arising from personal emergencies, illness, or missed flight connections not covered under provider waivers.</li>\n          <li>Special discounted, promotional tariffs, or peak holiday season bookings (December–January, festival weeks).</li>\n          <li>Visa rejections, passport expiry, or missing government documentation.</li>\n        </ul>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"processing-timeline\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">05</span>\n      <h3 class=\"policy-sec-title\">Refund Processing Timeline & Method</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <div class=\"refund-timeline-grid\">\n        <div class=\"timeline-step-card\">\n          <div class=\"step-num\">Step 1</div>\n          <div class=\"step-title\">Written Request</div>\n          <p>Customer sends written cancellation with booking ID.</p>\n        </div>\n        <div class=\"timeline-step-card\">\n          <div class=\"step-num\">Step 2</div>\n          <div class=\"step-title\">Vendor Audit</div>\n          <p>Audit of hotel, flight, and transport cancellation recovery.</p>\n        </div>\n        <div class=\"timeline-step-card\">\n          <div class=\"step-num\">Step 3</div>\n          <div class=\"step-title\">7–14 Days Credit</div>\n          <p>Approved refunds credited to the original payment source.</p>\n        </div>\n      </div>\n      <p class=\"policy-note\" style=\"margin-top: 16px;\"><em>Note: Wonderer South India is not liable for intermediate banking delays or international card processing holidays.</em></p>\n    </div>\n  </section>\n\n  <section id=\"amendments-rescheduling\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">06</span>\n      <h3 class=\"policy-sec-title\">Amendments & Tour Rescheduling</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <ul class=\"policy-list\">\n        <li>Date changes and itinerary adjustments are subject to room availability, vehicle scheduling, and provider fee structures.</li>\n        <li>Rescheduling requests must be placed in writing at least <strong>48 hours prior</strong> to the scheduled departure.</li>\n        <li>Any seasonal tariff difference or carrier rebooking penalty must be borne directly by the customer.</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"force-majeure\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">07</span>\n      <h3 class=\"policy-sec-title\">Force Majeure & Unforeseen Events</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>Wonderer South India shall not be held liable for monetary compensation or refund penalties arising from events beyond human control (Force Majeure), including:</p>\n      <ul class=\"policy-list\">\n        <li>Severe weather disruptions, floods, earthquakes, or natural disasters.</li>\n        <li>Sudden government travel restrictions, road closures, or curfew orders.</li>\n        <li>Public health emergencies or pandemics.</li>\n        <li>Civil disturbances, riots, or public transport strikes.</li>\n      </ul>\n      <p>In all such scenarios, we work tirelessly with partners to secure future travel credits wherever allowable.</p>\n    </div>\n  </section>\n\n  <section id=\"tramax-cancellations\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">08</span>\n      <h3 class=\"policy-sec-title\">Cancellations Initiated by Wonderer South India</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>In rare operational circumstances where Wonderer South India must cancel a scheduled tour, guests will be promptly offered:</p>\n      <div class=\"policy-options-grid\">\n        <div class=\"option-pill-card\">\n          <span class=\"option-tag\">Option A</span>\n          <strong>100% Full Refund</strong> of all monies paid directly to Wonderer South India.\n        </div>\n        <div class=\"option-pill-card\">\n          <span class=\"option-tag\">Option B</span>\n          <strong>Alternative Tour Package</strong> of equivalent value with upgraded amenities.\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"communication-updates\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">09</span>\n      <h3 class=\"policy-sec-title\">Mode of Communication & Policy Updates</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p><strong>Official Channels:</strong> All refund and cancellation claims must occur through official email or website communication channels. Verbal or unverified chat requests cannot be honored.</p>\n      <p><strong>Updates:</strong> Wonderer South India reserves the right to modify this Refund & Cancellation Policy at any time without prior notice. Updated terms take effect immediately upon publication.</p>\n    </div>\n  </section>\n\n  <section id=\"contact-refund\" class=\"policy-section-card policy-contact-highlight\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">10</span>\n      <h3 class=\"policy-sec-title\">Refund Inquiries & Support Helpdesk</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>For urgent cancellation requests or refund status tracking, please contact our helpdesk:</p>\n      <div class=\"policy-contact-grid\">\n        <div class=\"policy-contact-item\">\n          <strong>📧 Refunds Helpdesk:</strong> <a href=\"mailto:refunds@tramaxtours.in\">refunds@tramaxtours.in</a> / <a href=\"mailto:contact@tramaxtours.in\">contact@tramaxtours.in</a>\n        </div>\n        <div class=\"policy-contact-item\">\n          <strong>📞 Priority Helpline:</strong> <a href=\"tel:+918072566010\">+91 80725 66010</a> / <a href=\"tel:+919840291110\">+91 98402 91110</a>\n        </div>\n        <div class=\"policy-contact-item\">\n          <strong>📍 Helpdesk Hours:</strong> Mon – Sat: 9:00 AM – 7:00 PM IST\n        </div>\n      </div>\n    </div>\n  </section>\n</div>','Refund & Cancellation Policy | Wonderer South India','Read the official Refund and Cancellation Policy of Wonderer South India. Learn about eligibility, non-refundable situations, timelines, and rescheduling terms.','published',NULL,NULL,'2026-09-24 10:54:48','2026-09-30 04:46:16'),(4,'privacy-policy','Privacy Policy','Our commitment to safeguarding your personal information, data confidentiality, and user rights at Tramax Tours.',NULL,'<div class=\"policy-container-v2 privacy-policy-theme\">\n  <div class=\"policy-intro-box\">\n    <p class=\"policy-lead\">At <strong>Wonderer South India</strong>, we are committed to protecting your privacy and ensuring the security of your personal information.</p>\n    <p>This Privacy Policy explains how we collect, use, disclose, and safeguard your information when you visit our website or use our services.</p>\n  </div>\n\n  <section id=\"info-collected\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">01</span>\n      <h3 class=\"policy-sec-title\">Information We Collect</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>We may collect the following types of information when you interact with our platform:</p>\n      \n      <div class=\"policy-sub-card\">\n        <h4 class=\"policy-sub-title\">👤 Personal Information</h4>\n        <ul class=\"policy-list\">\n          <li><strong>Full Name:</strong> For identification and reservation vouchers.</li>\n          <li><strong>Email Address:</strong> For sending booking confirmations, itineraries, and receipts.</li>\n          <li><strong>Phone Number:</strong> For real-time trip coordination and chauffeur communication.</li>\n          <li><strong>Travel Preferences & Enquiries:</strong> Destination preferences, group size, and custom tour requests.</li>\n          <li><strong>Identification Details:</strong> Government-issued ID, Passport, or Visa info (only when strictly required for monument passes or flight/train reservations).</li>\n        </ul>\n      </div>\n\n      <div class=\"policy-sub-card\" style=\"margin-top: 16px;\">\n        <h4 class=\"policy-sub-title\">💻 Non-Personal & Technical Information</h4>\n        <ul class=\"policy-list\">\n          <li>Browser type, operating system, and screen resolution.</li>\n          <li>Device information and approximate geographic location.</li>\n          <li>IP address and anonymous analytical identifiers.</li>\n          <li>Website usage data (pages visited, time spent, interaction timestamps).</li>\n        </ul>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"how-we-use\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">02</span>\n      <h3 class=\"policy-sec-title\">How We Use Your Information</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>The information we collect is used purposefully to deliver seamless travel experiences:</p>\n      <ul class=\"policy-list\">\n        <li>Respond promptly to enquiries and customize your private itineraries.</li>\n        <li>Process reservations, hotel bookings, transportation, and payments.</li>\n        <li>Continuously improve our website performance, service quality, and guest experience.</li>\n        <li>Communicate itinerary updates, trip reminders, seasonal offers, or critical travel advisories.</li>\n        <li>Comply with applicable tourism regulations, taxation, and legal requirements.</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"sharing-info\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">03</span>\n      <h3 class=\"policy-sec-title\">Sharing of Information</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <div class=\"policy-highlight-badge\">\n        <span>🛡️ Strict Privacy Promise: We NEVER sell, trade, rent, or lease your personal data to any third-party marketing companies.</span>\n      </div>\n      <p style=\"margin-top: 14px;\">We share your information strictly on a need-to-know basis with:</p>\n      <ul class=\"policy-list\">\n        <li><strong>Verified Travel Partners:</strong> Hotels, airlines, chauffeur teams, and licensed tour guides for executing confirmed bookings.</li>\n        <li><strong>Regulatory & Government Authorities:</strong> When mandatory under applicable Indian or international law.</li>\n        <li><strong>Trusted Service Providers:</strong> Secure payment gateways, SMS/Email dispatchers who assist our operational infrastructure under non-disclosure agreements.</li>\n      </ul>\n    </div>\n  </section>\n\n  <section id=\"data-security\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">04</span>\n      <h3 class=\"policy-sec-title\">Data Security</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>We implement enterprise-grade technical and organizational security measures (including TLS/SSL encryption, restricted access protocols, and firewall protections) to protect your personal data against unauthorized access, alteration, or disclosure.</p>\n      <p class=\"policy-note\"><em>Note: While we adhere to top industry standards, no method of digital transmission or storage is 100% impenetrable. We constantly audit our systems to ensure safety.</em></p>\n    </div>\n  </section>\n\n  <section id=\"cookies\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">05</span>\n      <h3 class=\"policy-sec-title\">Cookies Policy</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>Our website utilizes secure cookies to:</p>\n      <ul class=\"policy-list\">\n        <li>Enhance user browsing experience and maintain session continuity.</li>\n        <li>Analyze aggregated traffic patterns to optimize page speed and navigation.</li>\n        <li>Remember your selected language and currency preferences.</li>\n      </ul>\n      <p>You can choose to disable cookies through your browser settings, though certain interactive features may experience limitations.</p>\n    </div>\n  </section>\n\n  <section id=\"third-party-links\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">06</span>\n      <h3 class=\"policy-sec-title\">Third-Party Links</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>Our website may contain links to third-party portals (such as external flight aggregators or tourism boards). Wonderer South India is not responsible for the privacy practices, policies, or content of such external websites. We encourage you to review their terms upon departure.</p>\n    </div>\n  </section>\n\n  <section id=\"user-rights\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">07</span>\n      <h3 class=\"policy-sec-title\">User Rights</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>You retain full control over your personal data. You have the right to:</p>\n      <ul class=\"policy-list\">\n        <li><strong>Access:</strong> Request a copy of the personal data we hold about you.</li>\n        <li><strong>Rectification:</strong> Request correction of inaccurate, outdated, or incomplete data.</li>\n        <li><strong>Erasure / Deletion:</strong> Request deletion of your personal records, subject to statutory accounting requirements.</li>\n        <li><strong>Withdraw Consent:</strong> Opt-out from promotional communications at any time.</li>\n      </ul>\n      <p>Requests can be submitted directly via our <strong>Contact Us</strong> page or official email.</p>\n    </div>\n  </section>\n\n  <section id=\"retention-children\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">08</span>\n      <h3 class=\"policy-sec-title\">Data Retention & Children\'s Privacy</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p><strong>Data Retention:</strong> We retain personal information only for as long as necessary to fulfill the trip execution, billing, dispute resolution, or as required by law.</p>\n      <p><strong>Children\'s Privacy:</strong> Our website services are not directed toward unaccompanied individuals under the age of 18. We do not knowingly collect personal information directly from children without parental or guardian consent.</p>\n    </div>\n  </section>\n\n  <section id=\"policy-changes-consent\" class=\"policy-section-card\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">09</span>\n      <h3 class=\"policy-sec-title\">Changes to This Policy & Consent</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>Wonderer South India reserves the right to update or modify this Privacy Policy at any time. Any changes will be published directly on this page with an updated revision timestamp.</p>\n      <p>By using our website or submitting your information for bookings or inquiries, you expressly consent to the practices described in this Privacy Policy.</p>\n    </div>\n  </section>\n\n  <section id=\"contact-privacy\" class=\"policy-section-card policy-contact-highlight\">\n    <div class=\"policy-sec-header\">\n      <span class=\"policy-sec-num\">10</span>\n      <h3 class=\"policy-sec-title\">Privacy Officer & Contact Information</h3>\n    </div>\n    <div class=\"policy-sec-body\">\n      <p>If you have any questions, concerns, or data requests regarding this Privacy Policy, please reach out to our privacy desk:</p>\n      <div class=\"policy-contact-grid\">\n        <div class=\"policy-contact-item\">\n          <strong>📧 Privacy Desk:</strong> <a href=\"mailto:privacy@tramaxtours.in\">privacy@tramaxtours.in</a> / <a href=\"mailto:contact@tramaxtours.in\">contact@tramaxtours.in</a>\n        </div>\n        <div class=\"policy-contact-item\">\n          <strong>📞 Telephone:</strong> <a href=\"tel:+918072566010\">+91 80725 66010</a> / <a href=\"tel:+919840291110\">+91 98402 91110</a>\n        </div>\n        <div class=\"policy-contact-item\">\n          <strong>📍 Address:</strong> Wonderer South India Head Office, Chennai, Tamil Nadu, India\n        </div>\n      </div>\n    </div>\n  </section>\n</div>','Privacy Policy | Wonderer South India','Learn how Wonderer South India protects and respects your privacy. Read our detailed information collection, data security, and cookies policy.','published',NULL,NULL,'2026-09-24 10:54:48','2026-09-30 04:46:16');
