INSERT INTO `reviews` VALUES (50,138,NULL,'marc','marc@example.com','india',5,'Delighted Traveler','Tour is very nice','uploads/media/demo_thingstodo_kerala_art.jpg','approved',1,458,'2026-11-11 01:09:01','2026-11-11 06:39:01','2026-11-11 06:39:01',NULL,NULL),(51,144,NULL,'Dr. Elena Rostova','elena.rostova@traveler.de','Germany',5,'Unforgettable South India Odyssey','Exploring Kerala and Tamil Nadu with a private chauffeur from Wanderer South India was the best decision we made. Our driver was polite, extremely knowledgeable about temple history, and the car was spotless every morning. Total peace of mind!','/uploads/media/demo_home_tamilnadu.jpg','approved',1,NULL,NULL,'2026-11-14 07:24:30','2026-11-14 07:24:30',NULL,NULL),(52,150,NULL,'David & Sarah Miller','miller.travels@ukmail.co.uk','United Kingdom',5,'Magnificent Heritage & Shore Temples','The Mahabalipuram and Kanchipuram day tours were breathtaking! The rock relief carvings and seaside Shore Temple were brought to life by our private guide. The Pay on Arrival booking option was super smooth and reassuring.','/uploads/media/demo_tamilnadu_mahabalipuram.jpg','approved',1,NULL,NULL,'2026-11-14 07:24:30','2026-11-14 07:24:30',NULL,NULL),(53,170,NULL,'Arjun & Priya Sharma','arjun.sharma@gmail.com','India',5,'Mystical Palm Leaf Horoscope Experience','We booked the sacred Palm Leaf Nadi Horoscope reading and temple tour in Vaitheeswaran Kovil. Finding my ancient leaf from thumbprint was an astonishing and deeply spiritual revelation. Superbly organized!','/uploads/media/palmleaf_sage_astrology.jpg','approved',1,NULL,NULL,'2026-11-14 07:24:30','2026-11-14 07:24:30',NULL,NULL),(54,142,NULL,'Thomas & Claudia Weber','thomas.weber@munich-travel.de','Germany',5,'First-Class Chauffeur & Tea Gardens','Munnar mist heights and Alleppey houseboats were paradise. Wanderer South India took care of every single transfer with luxury AC vehicles. Excellent English communication and prompt WhatsApp updates throughout.','/uploads/media/demo_carousel_munnar.jpg','approved',1,NULL,NULL,'2026-11-14 07:24:30','2026-11-14 07:24:30',NULL,NULL),(55,169,NULL,'Lucas Dubois','lucas.dubois@paris-voyage.fr','France',5,'Incredible Waves at Covelong Point','Surfing Covelong waves was the highlight of my trip to Tamil Nadu! Certified ocean instructors made me catch my first clean wave in under 45 minutes. Safe, exhilarating, and highly recommended!','/uploads/media/surfing_tour_banner.jpg','approved',1,NULL,NULL,'2026-11-14 07:24:30','2026-11-14 07:24:30',NULL,NULL),(56,145,NULL,'Kavitha & Ramesh Sundaram','kavitha.sundaram@sgmail.com','Singapore',5,'Golden Chidambaram & Thanjavur Circuit','Brought my elderly parents for a temple pilgrimage across Thanjavur Big Temple and Madurai Meenakshi. The chauffeur was extraordinarily attentive, patient, and handled luggage effortlessly. A 5-star experience!','/uploads/media/demo_tamilnadu_thanjavur.jpg','approved',1,NULL,NULL,'2026-11-14 07:24:30','2026-11-14 07:24:30',NULL,NULL);
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

