INSERT INTO `tour_categories` VALUES (1,'Cultural Tour','cultural-tour','#0284c7',NULL,'Heritage monuments, royal palaces, and ancient temple architecture.',0,'active','2026-10-01 14:52:50','2026-10-01 14:52:50'),(2,'Pilgrimage','pilgrimage','#0284c7',NULL,'Spiritual circuits, sacred temples, and holy South India shrines.',0,'active','2026-10-01 14:52:50','2026-10-01 14:52:50'),(3,'Beach Holiday','beach-holiday','#0284c7',NULL,'Pristine coastal retreats, coconut groves, and sun-kissed shores.',0,'active','2026-10-01 14:52:50','2026-10-01 14:52:50'),(4,'Adventure Tour','adventure-tour','#0284c7',NULL,'Western Ghats trekking, wildlife safaris, and outdoor expeditions.',0,'active','2026-10-01 14:52:50','2026-10-01 14:52:50'),(5,'Wildlife Tour','wildlife-tour','#0284c7',NULL,'National parks, tiger reserves, elephant sanctuaries, and birding.',0,'active','2026-10-01 14:52:50','2026-10-01 14:52:50'),(6,'Shopping Tour','shopping-tour','#0284c7',NULL,'Silk weaving centers, spice bazaars, handicrafts, and artisanal markets.',0,'active','2026-10-01 14:52:50','2026-10-01 14:52:50'),(8,'Surfing Tours','surfing-tour','#0284c7',NULL,'Professional ocean wave surfing lessons with certified ISA surf coaches at Covelong Point.',9,'active','2026-11-05 09:26:23','2026-11-12 04:57:46'),(9,'Medical Tourism & Health Checks','medical-tourism','#0284c7',NULL,'Comprehensive executive health checkups, preventive diagnostics and holistic wellness.',11,'active','2026-11-05 09:26:23','2026-11-12 04:57:46'),(10,'Palmleaf Horoscope Tours','palmleaf-horoscope','#d97706',NULL,'Ancient Maharishi Agastya Nadi Astrology reading and destiny discovery at Vaitheeswaran Kovil.',10,'active','2026-11-11 07:50:52','2026-11-12 04:57:46'),(11,'City Sightseeing Tours','city-sightseeing-tours','#0284c7',NULL,'Iconic urban landmarks, bustling markets, panoramic view-points, and modern cultural highlights.',1,'active','2026-11-12 04:57:46','2026-11-12 04:57:46'),(12,'Cultural & Heritage Tours','cultural-heritage-tours','#0284c7',NULL,'Living heritage monuments, royal palaces, UNESCO world heritage sites, and classical traditions.',2,'active','2026-11-12 04:57:46','2026-11-12 04:57:46'),(13,'Family Tours','family-tours','#0284c7',NULL,'Curated vacations tailored for families and small groups wanting scenic beauty and cultural encounters.',3,'active','2026-11-12 04:57:46','2026-11-12 04:57:46'),(14,'Guided Tours','guided-tours','#0284c7',NULL,'Expert localized commentary with licensed government storytellers and native scholars.',4,'active','2026-11-12 04:57:46','2026-11-12 04:57:46'),(15,'Historical Tours','historical-tours','#0284c7',NULL,'Ancient fortifications, megalithic rock carvings, colonial settlements, and archaeological ruins.',5,'active','2026-11-12 04:57:46','2026-11-12 04:57:46'),(16,'One Day Tours','one-day-tours','#0284c7',NULL,'Full-day and half-day immersive excursions with private chauffeur transport from city centers.',6,'active','2026-11-12 04:57:46','2026-11-12 04:57:46'),(17,'Pilgrimage / Temple Tours','pilgrimage-temple-tours','#0284c7',NULL,'Spiritual circuits, sacred Dravidian temple architecture, holy tanks, and ancient pooja rituals.',7,'active','2026-11-12 04:57:46','2026-11-12 04:57:46'),(18,'Private Tours','private-tours','#0284c7',NULL,'Exclusive personalized itineraries with private air-conditioned vehicle and bespoke schedule.',8,'active','2026-11-12 04:57:46','2026-11-12 04:57:46');
/*!40000 ALTER TABLE `tour_categories` ENABLE KEYS */;
UNLOCK TABLES;

