INSERT INTO `tour_highlights` VALUES (5,150,'Full-day Mahabalipuram local sightseeing tour',NULL,0,'2026-09-26 07:03:29','2026-09-26 07:03:29'),(6,150,'Duration: 10 hours',NULL,1,'2026-09-26 07:03:29','2026-09-26 07:03:29'),(7,150,'Private cab tour (not shared with others)',NULL,2,'2026-09-26 07:03:29','2026-09-26 07:03:29'),(8,150,'Pickup and drop from your Chennai hotel / residence',NULL,3,'2026-09-26 07:03:29','2026-09-26 07:03:29'),(30,169,'\"Surfing is not a sport, it’s a lifestyle\" — Turn your dream of being a surfer into reality',NULL,1,'2026-11-11 07:50:52','2026-11-11 07:50:52'),(31,169,'Whether you know how to swim or not, our guides coach you to surf independently with no fear',NULL,2,'2026-11-11 07:50:52','2026-11-11 07:50:52'),(32,169,'Structured lessons: 30-minute theatrical lesson + 1-hour practical in-water session',NULL,3,'2026-11-11 07:50:52','2026-11-11 07:50:52'),(33,169,'For beginners: equipment & safety instructions, board handling, and standing up close to shore',NULL,4,'2026-11-11 07:50:52','2026-11-11 07:50:52'),(34,169,'For intermediators: refresher on basics, paddling out behind the break & catching green waves solo',NULL,5,'2026-11-11 07:50:52','2026-11-11 07:50:52'),(35,169,'All-inclusive package: 1. Transport, 2. Surfing theory and practical lessons, 3. Dedicated Guide',NULL,6,'2026-11-11 07:50:52','2026-11-11 07:50:52'),(36,169,'Open Every Day from 8:00 AM to 6:00 PM with flexible booking slots',NULL,7,'2026-11-11 07:50:52','2026-11-11 07:50:52'),(44,170,'Nadi, in the ancient language of Tamil, means “in search of” — Find your purpose and direction',NULL,1,'2026-11-12 05:06:25','2026-11-12 05:06:25'),(45,170,'Dictated 3,000 years ago by Maharishis on special Palm Leaves specifically for your life path',NULL,2,'2026-11-12 05:06:25','2026-11-12 05:06:25'),(46,170,'Procedure 1: Searching for bundle(s) using your unique thumb impression and country of birth',NULL,3,'2026-11-12 05:06:25','2026-11-12 05:06:25'),(47,170,'Procedure 2: Moderated matching process by expert reader to locate your one personal Palm Leaf',NULL,4,'2026-11-12 05:06:25','2026-11-12 05:06:25'),(48,170,'Procedure 3: The Reading — reveals your destiny and guides you through life changing crossroads',NULL,5,'2026-11-12 05:06:25','2026-11-12 05:06:25'),(49,170,'Price for palm leaf horoscope: 7,000 INR per person — includes 1. Translator, 2. Transportation',NULL,6,'2026-11-12 05:06:25','2026-11-12 05:06:25'),(50,170,'Opening Times: Every Day from 10:00 AM to 6:00 PM with personalized care',NULL,7,'2026-11-12 05:06:25','2026-11-12 05:06:25');
