INSERT INTO `tour_itineraries` VALUES (5,150,'Morning (08:30 AM - 11:00 AM)','Pickup & Shore Temple Exploration','Pickup from your Chennai hotel / residence in a private air-conditioned vehicle. Drive along the scenic East Coast Road (ECR) to Mahabalipuram and visit the iconic Shore Temple, an 8th-century UNESCO World Heritage Site overlooking the Bay of Bengal.',0,'active','2026-09-26 07:03:29','2026-09-26 07:03:29'),(6,150,'Late Morning (11:00 AM - 01:30 PM)','Krishna\'s Butter Ball, Arjuna\'s Penance & Pancha Rathas','Explore the gravity-defying Krishna\'s Butter Ball natural boulder. Marvel at Arjuna\'s Penance (Descent of the Ganges) stone relief carving, and walk through the monolithic Pancha Rathas (Five Rathas) rock-cut shrines.',1,'active','2026-09-26 07:03:29','2026-09-26 07:03:29'),(7,150,'Afternoon (01:30 PM - 03:00 PM)','Authentic Lunch Break & Local Handicrafts','Relax and savor authentic South Indian or fresh seafood lunch at a beachside restaurant. Browse traditional stone carving workshops and local seashell handicrafts.',2,'active','2026-09-26 07:03:29','2026-09-26 07:03:29'),(8,150,'Evening (03:30 PM - 06:30 PM)','Covelong Beach & ISKCON Temple Return Drive','Stop by scenic Covelong Beach for refreshing coastal breezes, followed by a visit to the grand ISKCON Temple in Akkarai. Drive back and drop off safely at your Chennai residence/hotel.',3,'active','2026-09-26 07:03:29','2026-09-26 07:03:29'),(18,169,'30 Minutes','Theatrical Lesson & Ocean Safety Instructions','Equipment instructions and safety orientation on the sand. Learn how to handle the board in the water, understand rip currents, and practice pop-up mechanics.',1,'active','2026-11-11 07:50:52','2026-11-11 07:50:52'),(19,169,'60 Minutes','Practical In-Water Wave Session','Hands-on wave riding with your instructor. Beginners practice popping up on the board and riding first waves close to the beach; intermediators paddle out behind breaking waves and take green waves independently.',2,'active','2026-11-11 07:50:52','2026-11-11 07:50:52'),(20,169,'Post-Session','Debrief, Refreshments & Return Transport','Review technique tips with your guide, enjoy fresh tender coconut by the beach, and return via private air-conditioned vehicle.',3,'active','2026-11-11 07:50:52','2026-11-11 07:50:52'),(24,170,'Step 1','Searching for Bundle(s)','As soon as we get the appointment, we use your thumb impression, including in which country you were born in, and the search will commence. Our expert readers in India will physically search for your Palm Leaf bundle(s), which might contain your individual Palm Leaf.',1,'active','2026-11-12 05:06:25','2026-11-12 05:06:25'),(25,170,'Step 2','Matching Process','Preparation for the matching process by moderator; Once the reader has found your bundle(s) that might contain your Palm Leaf, the matching process and thus the search for your one personal Palm Leaf within the bundle(s) begins.',2,'active','2026-11-12 05:06:25','2026-11-12 05:06:25'),(26,170,'Step 3','The Reading & Destiny Revelations','The reading is the most important part of your experience. Based on your individual Palm Leaf, which was identified during the preceding matching process, this final part will let you know about your life.',3,'active','2026-11-12 05:06:25','2026-11-12 05:06:25');
/*!40000 ALTER TABLE `tour_itineraries` ENABLE KEYS */;
UNLOCK TABLES;

