ily'),(142,122,'Kerala Signature Luxury & Heritage Odyssey','kerala-signature-luxury-experience','Experience private chauffeur-guided excursions, 5-star heritage villas, and gourmet dining across Kerala.','A handpicked luxury expedition exploring the quintessential highlights and concealed gems of Kerala.',NULL,'Cultural & Heritage Tours',NULL,NULL,5,NULL,381,749.00,'USD',1,NULL,NULL,NULL,NULL,13,NULL,NULL,NULL,NULL,1,1,'published','2026-09-26 06:13:02','2026-11-14 07:28:26',NULL,1,20,20,1,'Daily'),(143,122,'Kerala Scenic Highlights & Family Explorer','kerala-scenic-family-getaway','Delightful family-friendly journeys with cultural immersion and scenic countryside trails in Kerala.','An effortless vacation tailored for families and small groups wanting scenic beauty and cultural encounters.',NULL,'Family Tours',NULL,NULL,4,NULL,374,499.00,'USD',1,NULL,NULL,NULL,NULL,13,NULL,NULL,NULL,NULL,1,2,'published','2026-09-26 06:13:02','2026-11-12 04:57:47',NULL,NULL,20,20,1,'Daily'),(144,123,'Tamil Nadu Signature Luxury & Heritage Odyssey','tamil-nadu-signature-luxury-experience','Experience private chauffeur-guided excursions, 5-star heritage villas, and gourmet dining across Tamil Nadu.','A handpicked luxury expedition exploring the quintessential highlights and concealed gems of Tamil Nadu.',NULL,'Cultural & Heritage Tours',NULL,NULL,5,NULL,437,749.00,'USD',1,NULL,NULL,NULL,NULL,13,NULL,NULL,NULL,NULL,1,1,'published','2026-09-26 06:13:02','2026-11-14 07:28:26',NULL,1,20,20,1,'Daily'),(145,123,'Tamil Nadu Scenic Highlights & Family Explorer','tamil-nadu-scenic-family-getaway','Delightful family-friendly journeys with cultural immersion and scenic countryside trails in Tamil Nadu.','An effortless vacation tailored for families and small groups wanting scenic beauty and cultural encounters.',NULL,'Family Tours',NULL,NULL,4,NULL,422,499.00,'USD',1,NULL,NULL,NULL,NULL,13,NULL,NULL,NULL,NULL,1,2,'published','2026-09-26 06:13:02','2026-11-14 07:28:26',NULL,1,20,20,1,'Daily'),(150,123,'Mahabalipuram Day Tour','mahabalipuram-day-tour','Step back in time with our Mahabalipuram Day Tour, exploring one of Tamil Nadu\'s most iconic heritage destinations.','<p>Step back in time with our <strong>Mahabalipuram Day Tour</strong>, exploring one of Tamil Nadu\'s most iconic heritage destinations. Also known as <strong>Mamallapuram</strong>, this ancient port town dates back to the <strong>7th–9th century Pallava dynasty</strong> and is renowned for its rock-cut monuments and UNESCO World Heritage Sites carved entirely from granite.</p><p>This tour offers a perfect blend of <strong>history, architecture, spirituality, and coastal beauty</strong>, making it ideal for culture lovers, history enthusiasts, and families.</p>',NULL,'One Day Tours','1 Day (8 Hours)',10.00,1,'English, Tamil',427,45.00,'EUR',1,NULL,'Mahabalipuram UNESCO Heritage Circuit',12.61670000,80.19280000,14,NULL,NULL,NULL,NULL,1,1,'published','2026-09-26 06:31:05','2026-11-12 04:57:46',NULL,NULL,20,20,1,'Daily'),(151,123,'Kanchipuram Day Tour','kanchipuram-day-tour','Private day excursion covering the iconic landmarks and cultural gems of kanchipuram.','Enjoy a seamless private air-conditioned vehicle with expert chauffeur guide exploring top historical monuments and photo spots.',NULL,'One Day Tours','1 Day (9 Hours)',NULL,1,NULL,417,49.00,'USD',1,NULL,NULL,NULL,NULL,13,NULL,NULL,NULL,NULL,1,2,'published','2026-09-26 06:31:05','2026-11-14 07:28:26',NULL,1,20,20,1,'Daily'),(152,123,'PONDICHERRY DAY TOUR','pondicherry-day-tour','Private day excursion covering the iconic landmarks and cultural gems of pondicherry.','Enjoy a seamless private air-conditioned vehicle with expert chauffeur guide exploring top historical monuments and photo spots.',NULL,'One Day Tours','1 Day (12 Hours)',NULL,1,NULL,432,65.00,'USD',1,NULL,NULL,NULL,NULL,13,NULL,NULL,NULL,NULL,1,3,'published','2026-09-26 06:31:05','2026-11-12 04:57:46',NULL,NULL,20,20,1,'Daily'),(153,123,'Chennai Day Tour','chennai-day-tour','Private day excursion covering the iconic landmarks and cultural gems of chennai.','Enjoy a seamless private air-conditioned vehicle with expert chauffeur guide exploring top historical monuments and photo spots.',NULL,'One Day Tours','1 Day (8 Hours)',NULL,1,NULL,412,39.00,'USD',1,NULL,NULL,NULL,NULL,13,NULL,NULL,NULL,NULL,1,4,'published','2026-09-26 06:31:06','2026-11-14 07:28:26',NULL,1,20,20,1,'Daily'),(169,123,'SURFING (YOUR BEST DAY)','surfing-your-best-day','\"Surfing is not a sport, it’s a lifestyle.\" We help you to make your dream of being a surfer a reality. Whether you know how to swim or not, we will guide you so that you can surf independently with no fear. Just like a pro surfer.','<p class=\"lead\"><strong>\"Surfing is not a sport, it’s a lifestyle\"</strong></p>\n<p>When we say that surfing is a lifestyle, we mean it. We help you to make your dream of being a surfer a reality.</p>\n<p>Whether you know how to swim or not, we will guide you so that you can surf independently with no fear. Just like a pro surfer.</p>\n\n<div class=\"surfing-lessons-info\" style=\"margin: 20px 0; padding: 18px; background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 12px;\">\n  <h3 style=\"color: #166534; margin: 0 0 10px 0; font-size: 18px;\">🏄 Surfing Lessons Structure</h3>\n  <ul style=\"margin: 0; padding-left: 20px; color: #15803d; line-height: 1.8;\">\n    <li><strong>Theatrical lesson for a half hour:</strong> Essential equipment knowledge, safety instructions, rip-current awareness, and board control.</li>\n    <li><strong>Practical session for one hour:</strong> Dedicated in-water ocean coaching to catch and ride your waves safely.</li>\n  </ul>\n</div>\n\n<div class=\"curriculum-grid\" style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 16px; margin: 20px 0;\">\n  <div style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 18px; box-shadow: 0 2px 6px rgba(0,0,0,0.03);\">\n    <h4 style=\"color: #0f172a; margin: 0 0 10px 0; font-size: 16px;\">🌱 What do you learn? (For Beginners)</h4>\n    <ul style=\"margin: 0; padding-left: 20px; color: #475569; line-height: 1.8;\">\n      <li>Equipment and safety instructions</li>\n      <li>How to handle the board in the water</li>\n      <li>How to stand up on a board</li>\n      <li>Surf your first waves close to the beach</li>\n    </ul>\n  </div>\n\n  <div style=\"background: #ffffff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 18px; box-shadow: 0 2px 6px rgba(0,0,0,0.03);\">\n    <h4 style=\"color: #0f172a; margin: 0 0 10px 0; font-size: 16px;\">🌊 What do you learn? (For Intermediators)</h4>\n    <ul style=\"margin: 0; padding-left: 20px; color: #475569; line-height: 1.8;\">\n      <li>Refresher on basics, equipment and safety</li>\n      <li>How to paddle out behind the breaking waves</li>\n      <li>How to take green waves on your own</li>\n    </ul>\n  </div>\n</div>\n\n<div style=\"display: flex; flex-wrap: wrap; gap: 16px; margin: 20px 0;\">\n  <div style=\"flex: 1; min-width: 240px; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px;\">\n    <h4 style=\"color: #0f172a; margin: 0 0 6px 0; font-size: 15px;\">🕒 Opening Times</h4>\n    <p style=\"margin: 0; color: #334155; font-weight: 600;\">Every Day from 8:00 AM to 6:00 PM</p>\n  </div>\n\n  <div style=\"flex: 1; min-width: 240px; background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 12px; padding: 16px;\">\n    <h4 style=\"color: #1e40af; margin: 0 0 6px 0; font-size: 15px;\">📞 Direct Tour Organizer Contact</h4>\n    <p style=\"margin: 0 0 4px 0; color: #1e3a8a;\"><strong>E-Mail:</strong> <a href=\"mailto:welcome@yourbestdayinindia.com\" style=\"color: #2563eb; text-decoration: none;\">welcome@yourbestdayinindia.com</a></p>\n    <p style=\"margin: 0; color: #1e3a8a;\"><strong>Phone &amp; WhatsApp:</strong> <a href=\"https://wa.me/919840291110\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color: #2563eb; text-decoration: none; font-weight: 600;\">+91 9840291110</a></p>\n  </div>\n</div>','{\"opening_times\": \"Every Day from 8:00 AM to 6:00 PM\", \"organizer_email\": \"welcome@yourbestdayinindia.com\", \"organizer_phone\": \"+91 9840291110\", \"experience_details\": [{\"title\": \"Theatrical lesson for a half hour\", \"description\": \"Equipment instructions, ocean currents, safety protocols, and board control basics.\"}, {\"title\": \"Practical session for one hour\", \"description\": \"Hands-on ocean wave catching with personal guidance from your instructor.\"}], \"organizer_whatsapp\": \"+91 9840291110\"}','Surfing Tours','1.5 Hours Lesson (Daily 8 AM - 6 PM)',1.50,1,'English, Tamil',504,5000.00,'INR',1,12,'Covelong Point Surf Village & Beach',12.79180000,80.25200000,13,'SURFING (YOUR BEST DAY) — Surfing Lessons in India','Learn to surf in South India with certified guides. 30-min theory + 1-hour ocean wave session. Transport, lessons & guide included.',NULL,NULL,1,1,'published','2026-11-05 10:11:53','2026-11-12 04:57:47',NULL,NULL,20,20,1,'Daily (8:00 AM - 6:00 PM)'),(170,123,'PALMLEAF HOROSCOPE (FIND YOUR DESTINY)','palmleaf-horoscope-find-your-destiny','Nadi, in the ancient language of Tamil, means “in search of”. Dictated 3,000 years ago by Maharishis on sacred Palm Leaves specifically for you. Complete 3-procedure reading with dedicated translator and private transport included.','<p class=\"lead\"><strong>PALMLEAF HOROSCOPE (FIND YOUR DESTINY)</strong></p>\n<p><strong>Nadi</strong>, in the ancient language of Tamil, means <em>“in search of”</em>. Because an individual goes in search of the predictions made for them, to find purpose and direction, the entire system of the Maharishis’ insights and predictions eventually came to be called by this name, <strong>Nadi Astrology</strong>.</p>\n<p>Three thousand years ago, personal information about you was dictated by the Maharishis to their disciples and handwritten on special Palm Leaves, also called Nadis. These Palm Leaves were preserved for all this time, for you to access their contents when you need it most. Your Palm Leaf was written specifically for you, to provide you with guidance during the most important times of your life, by allowing you to prepare for future life changing events.</p>\n<p>If you are approaching this crossroad in your life, then your Palm Leaf begins to draw you upon the search for its contents.</p>\n\n<div class=\"procedures-container\" style=\"margin: 24px 0; padding: 20px; background: #fffbeb; border: 1px solid #fde68a; border-radius: 14px;\">\n  <h3 style=\"color: #92400e; margin: 0 0 16px 0; font-size: 19px;\">📜 Procedures for Palm Leaf Reading</h3>\n\n  <div style=\"margin-bottom: 16px; padding: 14px; background: #ffffff; border-radius: 10px; border-left: 4px solid #d97706;\">\n    <h4 style=\"margin: 0 0 6px 0; color: #78350f; font-size: 16px;\">1. Searching for bundle(s)</h4>\n    <p style=\"margin: 0; color: #4b5563; line-height: 1.65;\">As soon as we get the appointment, we use your thumb impression, including in which country you were born in, the search will commence. Our expert readers in India will physically search for your Palm Leaf bundle(s), which might contain your individual Palm Leaf.</p>\n  </div>\n\n  <div style=\"margin-bottom: 16px; padding: 14px; background: #ffffff; border-radius: 10px; border-left: 4px solid #d97706;\">\n    <h4 style=\"margin: 0 0 6px 0; color: #78350f; font-size: 16px;\">2. Matching</h4>\n    <p style=\"margin: 0; color: #4b5563; line-height: 1.65;\">Preparation for the matching process by moderator; Once the reader has found your bundle(s) that might contain your Palm Leaf, the matching process and thus the search for your one personal Palm Leaf within the bundle(s) begins.</p>\n  </div>\n\n  <div style=\"padding: 14px; background: #ffffff; border-radius: 10px; border-left: 4px solid #d97706;\">\n    <h4 style=\"margin: 0 0 6px 0; color: #78350f; font-size: 16px;\">3. Reading</h4>\n    <p style=\"margin: 0; color: #4b5563; line-height: 1.65;\">The reading is the most important part of your experience. Based on your individual Palm Leaf, which was identified during the preceding matching process, this final part will let you know about your life.</p>\n  </div>\n</div>\n\n<div style=\"display: flex; flex-wrap: wrap; gap: 16px; margin: 20px 0;\">\n  <div style=\"flex: 1; min-width: 240px; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px;\">\n    <h4 style=\"color: #0f172a; margin: 0 0 6px 0; font-size: 15px;\">🕒 Opening Times</h4>\n    <p style=\"margin: 0; color: #334155; font-weight: 600;\">Every Day from 10:00 AM to 6:00 PM</p>\n  </div>\n\n  <div style=\"flex: 1; min-width: 240px; background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 12px; padding: 16px;\">\n    <h4 style=\"color: #166534; margin: 0 0 6px 0; font-size: 15px;\">💰 Price &amp; Inclusions</h4>\n    <p style=\"margin: 0 0 4px 0; color: #15803d; font-weight: 700;\">7,000 INR per person</p>\n    <p style=\"margin: 0; color: #166534; font-size: 13.5px;\">Includes: 1. Translator | 2. Transportation</p>\n  </div>\n</div>\n\n<div style=\"background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 12px; padding: 16px; margin: 20px 0;\">\n  <h4 style=\"color: #1e40af; margin: 0 0 6px 0; font-size: 15px;\">📞 Contact Organizer</h4>\n  <p style=\"margin: 0 0 4px 0; color: #1e3a8a;\"><strong>E-Mail:</strong> <a href=\"mailto:welcome@yourbestdayinindia.com\" style=\"color: #2563eb; text-decoration: none;\">welcome@yourbestdayinindia.com</a></p>\n  <p style=\"margin: 0; color: #1e3a8a;\"><strong>Phone &amp; WhatsApp:</strong> <a href=\"https://wa.me/919840291110\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color: #2563eb; text-decoration: none; font-weight: 600;\">+91 9840291110</a></p>\n</div>','{\"procedures\": {\"3. Reading\": \"The reading is the most important part of your experience. Based on your individual Palm Leaf, this final part lets you know about your life.\", \"2. Matching\": \"Preparation for the matching process by moderator; Once the reader has found your bundle(s), the matching process begins.\", \"1. Searching for bundle(s)\": \"As soon as we get the appointment, we use your thumb impression, including in which country you were born in, the search will commence.\"}, \"opening_times\": \"Every Day from 10:00 AM to 6:00 PM\", \"organizer_email\": \"welcome@yourbestdayinindia.com\", \"organizer_phone\": \"+91 9840291110\", \"organizer_whatsapp\": \"+91 9840291110\"}','Palmleaf Horoscope Tours','Daily from 10 AM to 6 PM',4.00,1,'English, Tamil (Translator Included)',501,7000.00,'INR',1,8,'Nadi Astrology Palmleaf Center & Vaitheeswaran Kovil',11.20140000,79.72890000,13,'PALMLEAF HOROSCOPE (FIND YOUR DESTINY) — Nadi Astrology India','Discover your destiny through 3,000-year-old Maharishi Palm Leaves. 3-step reading with personal translator and AC transport included.',NULL,NULL,1,2,'published','2026-11-11 07:50:52','2026-11-12 05:06:25',NULL,NULL,20,20,1,'Daily (10:00 AM - 6:00 PM)');
